        built.append(kind)
        return orig(self, kind, *a, **kw)

    monkeypatch.setattr(Parser, "parse_error", spy)
    loads("a = []\nb = [1, 2,]\nc = [\n 1,\n]\n")
    assert UnexpectedCharError not in built

